1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    min-height: 100vh;
12	    display: flex;
13	    align-items: center;
14	    justify-content: center;
15	    background: #e9ecef;
16	    font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
17	  }
18	  .calc {
19	    width: 320px;
20	    max-width: calc(100vw - 32px);
21	    background: #1f2328;
22	    border-radius: 20px;
23	    padding: 20px;
24	    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.25);
25	  }
26	  .display {
27	    color: #fff;
28	    font-size: 48px;
29	    text-align: right;
30	    padding: 16px 8px 20px;
31	    min-height: 88px;
32	    overflow: hidden;
33	    white-space: nowrap;
34	    text-overflow: ellipsis;
35	  }
36	  .keys {
37	    display: grid;
38	    grid-template-columns: repeat(4, 1fr);
39	    gap: 12px;
40	  }
41	  button {
42	    font: inherit;
43	    font-size: 24px;
44	    height: 64px;
45	    border: none;
46	    border-radius: 14px;
47	    background: #3a3f45;
48	    color: #fff;
49	    cursor: pointer;
50	  }
51	  button:active { filter: brightness(1.25); }
52	  button.op { background: #f59f00; }
53	  button.op.active { background: #fff; color: #f59f00; }
54	  button.clear { background: #868e96; }
55	  button.wide { grid-column: span 2; }
56	</style>
57	</head>
58	<body>
59	<div class="calc">
60	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
61	  <div class="keys">
62	    <button class="clear wide" data-testid="key-lparen">(</button>
63	    <button class="clear wide" data-testid="key-rparen">)</button>
64	
65	    <!-- [REQ-006] % key removed; AC spans its place. -->
66	    <button class="clear wide" data-testid="key-clear">AC</button>
67	    <button class="clear" data-testid="key-sign">±</button>
68	    <button class="op" data-testid="key-div" data-op="/">÷</button>
69	
70	    <button data-testid="key-7">7</button>
71	    <button data-testid="key-8">8</button>
72	    <button data-testid="key-9">9</button>
73	    <button class="op" data-testid="key-mul" data-op="*">×</button>
74	
75	    <button data-testid="key-4">4</button>
76	    <button data-testid="key-5">5</button>
77	    <button data-testid="key-6">6</button>
78	    <button class="op" data-testid="key-sub" data-op="-">−</button>
79	
80	    <button data-testid="key-1">1</button>
81	    <button data-testid="key-2">2</button>
82	    <button data-testid="key-3">3</button>
83	    <button class="op" data-testid="key-add" data-op="+">+</button>
84	
85	    <button class="wide" data-testid="key-0">0</button>
86	    <button data-testid="key-dot">.</button>
87	    <button class="op" data-testid="key-equals">=</button>
88	  </div>
89	</div>
90	<script>
91	  var display = document.querySelector('[data-testid="calc-display"]');
92	
93	  var state = {
94	    entry: '0',       // text of the number being shown/typed
95	    stored: null,     // left operand
96	    op: null,         // pending operator
97	    fresh: true,      // next digit starts a new entry
98	    typed: false,     // entry was typed by the user (shown as typed, not formatted)
99	    error: false,
100	    groups: []        // [REQ-005] saved {stored, op} of each open "(", innermost last
101	  };
102	
103	  // [REQ-003] Presentation only: at most 10 significant digits, no trailing
104	  // zeros, exponential when |v| >= 1e10 or < 1e-9. Never applied to stored values.
105	  function formatNumber(v) {
106	    var r = Number(v.toPrecision(10));
107	    if (r === 0) return '0';
108	    var abs = Math.abs(r);
109	    if (abs >= 1e10 || abs < 1e-9) {
110	      return r.toExponential(9).replace(/\.?0+e/, 'e');
111	    }
112	    var e = Math.floor(Math.log10(abs));
113	    var s = r.toFixed(Math.max(0, 10 - e));
114	    if (s.indexOf('.') !== -1) s = s.replace(/0+$/, '').replace(/\.$/, '');
115	    return s;
116	  }
117	
118	  // [REQ-001]
119	  function compute(a, op, b) {
120	    switch (op) {
121	      case '+': return a + b;
122	      case '-': return a - b;
123	      case '*': return a * b;
124	      case '/': return a / b;
125	    }
126	    return b;
127	  }
128	
129	  // [REQ-001]
130	  // [REQ-003] Rounding happens here only; data-value keeps the exact value.
131	  function render() {
132	    var value = Number(state.entry);
133	    display.textContent = state.error ? 'Error' : (state.typed ? state.entry : formatNumber(value));
134	    display.setAttribute('data-value', state.error ? 'NaN' : String(value));
135	    display.setAttribute('data-error', state.error ? 'true' : 'false');
136	    document.querySelectorAll('button[data-op]').forEach(function (b) {
137	      b.classList.toggle('active', state.fresh && state.op === b.getAttribute('data-op'));
138	    });
139	  }
140	
141	  // [REQ-001]
142	  // [REQ-003] Division by zero (non-finite result) enters the error state.
143	  // String(value) is exact: Number(String(v)) === v.
144	  function setResult(value) {
145	    if (!isFinite(value)) {
146	      state.error = true;
147	      state.entry = '0';
148	      state.stored = null;
149	      state.op = null;
150	      state.groups = [];
151	    } else {
152	      state.entry = String(value);
153	    }
154	    state.typed = false;
155	    state.fresh = true;
156	  }
157	
158	  // [REQ-001]
159	  // [REQ-003] Ignored in the error state; only clear leaves it.
160	  // [REQ-004] A value set by ± is finished: the next digit starts a new entry.
161	  function inputDigit(d) {
162	    if (state.error) return;
163	    if (state.fresh || !state.typed) {
164	      state.entry = d;
165	      state.fresh = false;
166	    } else if (state.entry === '0' || state.entry === '-0') {
167	      state.entry = state.entry.slice(0, -1) + d;
168	    } else {
169	      state.entry += d;
170	    }
171	    state.typed = true;
172	  }
173	
174	  // [REQ-001]
175	  // [REQ-003] Ignored in the error state.
176	  function inputDot() {
177	    if (state.error) return;
178	    if (state.fresh || !state.typed) {
179	      state.entry = '0.';
180	      state.fresh = false;
181	    } else if (state.entry.indexOf('.') === -1) {
182	      state.entry += '.';
183	    }
184	    state.typed = true;
185	  }
186	
187	  // [REQ-004] ± flips the current entry. While typing it flips the text, so
188	  // typing continues. Otherwise the flipped value becomes the current operand.
189	  function toggleSign() {
190	    if (state.error) return;
191	    if (state.typed && !state.fresh) {
192	      state.entry = state.entry.charAt(0) === '-' ? state.entry.slice(1) : '-' + state.entry;
193	    } else {
194	      setOperand(-Number(state.entry));
195	    }
196	  }
197	
198	  // [REQ-004] A finished value that counts as the right operand if an operator
199	  // is waiting (so 2 × ( 3 + 4 ) = is 14), and is replaced by the next digit.
200	  function setOperand(value) {
201	    state.entry = String(value);
202	    state.typed = false;
203	    state.fresh = false;
204	  }
205	
206	  // [REQ-001]
207	  // [REQ-002] Immediate execution: an operator key first finishes the waiting
208	  // operation, strictly left to right, no precedence. 2 + 3 × 4 = is 20.
209	  function inputOperator(op) {
210	    if (state.error) return;
211	    if (state.op !== null && !state.fresh) {
212	      setResult(compute(state.stored, state.op, Number(state.entry)));
213	      if (state.error) return;
214	    }
215	    state.stored = Number(state.entry);
216	    state.op = op;
217	    state.fresh = true;
218	  }
219	
220	  // [REQ-005] "(" saves the waiting operation and starts an empty group.
221	  // Whatever the group evaluates to replaces the current entry.
222	  function openGroup() {
223	    if (state.error) return;
224	    state.groups.push({ stored: state.stored, op: state.op });
225	    state.stored = null;
226	    state.op = null;
227	    state.entry = '0';
228	    state.fresh = true;
229	    state.typed = false;
230	  }
231	
232	  // [REQ-005] ")" finishes the innermost group, restores the operation that
233	  // was waiting outside it, and uses the group's value as its right operand.
234	  // Ignored when no group is open.
235	  function closeGroup() {
236	    if (state.error || state.groups.length === 0) return;
237	    var value = state.op === null ? Number(state.entry)
238	      : compute(state.stored, state.op, Number(state.entry));
239	    if (!isFinite(value)) { setResult(value); return; }
240	    var outer = state.groups.pop();
241	    state.stored = outer.stored;
242	    state.op = outer.op;
243	    setOperand(value);
244	  }
245	
246	  // [REQ-001]
247	  // [REQ-005] Open groups are closed first, so 2 × ( 3 + 4 = is 14.
248	  function equals() {
249	    if (state.error) return;
250	    while (state.groups.length > 0 && !state.error) closeGroup();
251	    if (state.error || state.op === null) return;
252	    var result = compute(state.stored, state.op, Number(state.entry));
253	    state.stored = null;
254	    state.op = null;
255	    setResult(result);
256	  }
257	
258	  // [REQ-001]
259	  function clearAll() {
260	    state.entry = '0';
261	    state.stored = null;
262	    state.op = null;
263	    state.fresh = true;
264	    state.typed = false;
265	    state.error = false;
266	    state.groups = [];
267	  }
268	
269	  document.querySelector('.keys').addEventListener('click', function (e) {
270	    var btn = e.target.closest('button');
271	    if (!btn) return;
272	    var id = btn.getAttribute('data-testid');
273	    if (/^key-\d$/.test(id)) inputDigit(id.slice(4));
274	    else if (id === 'key-dot') inputDot();
275	    else if (id === 'key-sign') toggleSign();
276	    else if (id === 'key-lparen') openGroup();
277	    else if (id === 'key-rparen') closeGroup();
278	    else if (id === 'key-equals') equals();
279	    else if (id === 'key-clear') clearAll();
280	    else if (btn.hasAttribute('data-op')) inputOperator(btn.getAttribute('data-op'));
281	    render();
282	  });
283	
284	  render();
285	</script>
286	</body>
287	</html>
